import {decodeTable,csvText,bboxContains,project} from './core.js';
import {summaryStats} from './charts.js';
let dataset=null,index=null,overview=null,loadSequence=0,controller=null;const cache=new Map();let overviewPromise=null;
function spatialIndex(rows){const bins=new Map();for(const r of rows){const k=Math.floor(r.经度*10)+","+Math.floor(r.纬度*10);if(!bins.has(k))bins.set(k,[]);bins.get(k).push(r)}return bins}
function spatialQuery(rows,bins,b){if(!b)return rows;const out=[];for(const[k,records]of bins){const[x,y]=k.split(",").map(Number);if((x+1)/10>=b[0]&&x/10<=b[2]&&(y+1)/10>=b[1]&&y/10<=b[3])out.push(...records)}return out}

async function readGzip(url,signal){const r=await fetch(url,{signal});if(!r.ok)throw Error('数据请求失败 '+r.status);if(!self.DecompressionStream)throw Error('此浏览器不支持压缩数据读取，请使用新版 Chrome、Edge、Safari 或 Firefox。');return JSON.parse(await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).text())}
function makeDataset(pack){const tables=Object.fromEntries(Object.entries(pack.tables).map(([k,v])=>[k,decodeTable(v)]));const demands=new Map(tables.candidates.map(r=>[r.候选点ID,r])),nodes=new Map(tables.centers.map(r=>[r.中心ID,r])),states=new Map(tables.demand_coverage.map(r=>[r.候选点ID,r])),virtual=new Map(tables.virtual_nodes.map(r=>[r.中心ID,r])),facilities=new Map(tables.facilities.map(r=>[r.facility_id,r])),parents=new Map(),children=new Map(),members=new Map();
 for(const r of tables.coverage){parents.set(r.点ID,r);if(!children.has(r.cluster_uid))children.set(r.cluster_uid,[]);children.get(r.cluster_uid).push(r)}for(const r of tables.centers){if(!members.has(r.facility_id))members.set(r.facility_id,[]);members.get(r.facility_id).push(r.中心ID)}
 return {pack,tables,demands,nodes,states,virtual,parents,children,facilities,members,demandsGrid:spatialIndex(tables.candidates),nodesGrid:spatialIndex(tables.centers)};}
function filtered(f,viewport=null){if(!dataset)return {demands:[],nodes:[]};const ds=dataset;
 const demands=spatialQuery(ds.tables.candidates,ds.demandsGrid,viewport).filter(r=>(!f.type||r.物流类型===f.type)&&(r.需求得分??0)>=Number(f.intensity||0)&&(!f.land||r.landuse_name===f.land)&&bboxContains(viewport,r.经度,r.纬度)&&(f.scenario==='baseline'?ds.states.get(r.候选点ID)?.baseline_complete_path:f.scenario==='added'?!ds.states.get(r.候选点ID)?.baseline_complete_path&&ds.states.get(r.候选点ID)?.planning_complete_path:true));
 const nodes=spatialQuery(ds.tables.centers,ds.nodesGrid,viewport).filter(r=>(f.levels||['DZ','LD','DC']).includes(r.层级)&&(f.nodeKind==='virtual'?r.is_virtual_plan===true:f.nodeKind==='inherited'?r.is_virtual_plan!==true:true)&&(!f.review||r.land_review===f.review)&&(!f.land||r.landuse_name===f.land)&&(!f.status||r.node_status===f.status)&&bboxContains(viewport,r.经度,r.纬度));return {demands,nodes};}
function metrics(demands,nodes){const ds=dataset;let base=0,plan=0,weight=0,bw=0,pw=0;const types={},poi={},levels={DZ:0,LD:0,DC:0},virtual={DZ:0,LD:0,DC:0},land={};for(const r of demands){const s=ds.states.get(r.候选点ID),w=r.规模权重||0;base+=+s.baseline_complete_path;plan+=+s.planning_complete_path;weight+=w;bw+=s.baseline_complete_path?w:0;pw+=s.planning_complete_path?w:0;types[r.物流类型||'未分类']=(types[r.物流类型||'未分类']||0)+1;for(const k of Object.keys(r)){if(k.includes('邻域')&&k.includes('数量'))poi[k]=(poi[k]||0)+(r[k]||0)}}for(const r of nodes){levels[r.层级]++;if(r.is_virtual_plan){virtual[r.层级]++;land[r.land_review]=(land[r.land_review]||0)+1}}return {demand_points:demands.length,baseline_covered:base,planning_covered:plan,total_weight:weight,baseline_weight:bw,planning_weight:pw,point_coverage:demands.length?base/demands.length:null,planning_point_coverage:demands.length?plan/demands.length:null,weight_coverage:weight?bw/weight:null,planning_weight_coverage:weight?pw/weight:null,nodes:levels,virtual,virtualLand:land,land_review:land.needs_review||0,virtual_total:Object.values(virtual).reduce((a,b)=>a+b,0),types,poi};}
function aggregate(points,view,force=false){const z=view.zoom||4,cell=(z<8?48:z<12?30:18),buckets=new Map();if(!force&&z>=13&&points.length<6500)return points;for(const p of points){const [x,y]=project(p.lng,p.lat,z),key=(p.city||'')+'|'+p.kind+'|'+p.level+'|'+Boolean(p.virtual)+'|'+Boolean(p.added)+'|'+Math.floor(x/cell)+'|'+Math.floor(y/cell);let a=buckets.get(key);if(!a){a={...p,lng:0,lat:0,count:0,weight:0,score:0,aggregate:true,ids:[]};buckets.set(key,a)}const n=p.count||1;a.lng+=p.lng*n;a.lat+=p.lat*n;a.count+=n;a.weight+=(p.weight||0);a.score+=p.score||0;if(a.ids.length<10)a.ids.push(p.id)}return [...buckets.values()].map(a=>({...a,lng:a.lng/a.count,lat:a.lat/a.count}));}
function renderCity(f,view){const all=filtered(f),visible=filtered(f,view.bounds),ds=dataset,points=[];
 if(f.showDemand)for(const r of visible.demands){const s=ds.states.get(r.候选点ID);points.push({id:r.候选点ID,lng:r.经度,lat:r.纬度,weight:r.规模权重||0,score:r.需求得分||0,kind:'demand',level:'demand',added:!s.baseline_complete_path&&s.planning_complete_path,count:1})}
 for(const r of visible.nodes)points.push({id:r.中心ID,lng:r.经度,lat:r.纬度,kind:'node',level:r.层级,virtual:r.is_virtual_plan,weight:r.簇权重总和||0,count:1});
 const table=f.exportKind==='centers'?all.nodes:all.demands;
 return {points:aggregate(points,view),metrics:metrics(all.demands,all.nodes),viewportMetrics:metrics(visible.demands,visible.nodes),visibleCount:points.length,list:table.slice(0,60).map(r=>({id:r.候选点ID||r.中心ID,name:r.名称||r.中心ID.split('|').at(-1),level:r.层级||'需求点',weight:r.规模权重??r.簇权重总和,virtual:r.is_virtual_plan,land:r.landuse_name})),listTotal:table.length};}
function renderNational(f,view){const allowed=index.cities.filter(s=>(!f.province||s.省份===f.province));const ids=new Set(allowed.map(s=>s.id));const points=[];const stats=summaryStats(allowed);let n=0,b=0,w=0,bw=0;for(const a of overview.rows){if(!ids.has(a[0])||(f.type&&a[1]!==f.type))continue;const count=f.scenario==='baseline'?a[6]:f.scenario==='added'?a[4]-a[6]:a[4],weight=f.scenario==='baseline'?a[7]:f.scenario==='added'?a[5]-a[7]:a[5];n+=count;b+=f.scenario==='added'?0:a[6];w+=weight;bw+=f.scenario==='added'?0:a[7];if(f.showDemand&&count&&bboxContains(view.bounds,a[2],a[3]))points.push({id:a[0],city:a[0],kind:'demand',level:'demand',lng:a[2],lat:a[3],count,weight,score:a[8],aggregate:true})}
 for(const s of allowed)for(const level of f.levels||[]){const n=f.nodeKind==='virtual'?s['virtual_'+level]:f.nodeKind==='inherited'?s['K_'+level]-s['virtual_'+level]:s['K_'+level];if(n&&s.center&&bboxContains(view.bounds,s.center[1],s.center[0]))points.push({id:s.id,city:s.id,kind:'node',level,lng:s.center[1],lat:s.center[0],count:n,virtual:f.nodeKind==='virtual',aggregate:true})}
 for(const level of ['DZ','LD','DC']){if(!(f.levels||[]).includes(level)){stats.nodes[level]=0;stats.virtual[level]=0}else if(f.nodeKind==='virtual'){stats.nodes[level]=stats.virtual[level]}else if(f.nodeKind==='inherited'){stats.nodes[level]-=stats.virtual[level];stats.virtual[level]=0}}stats.virtual_total=Object.values(stats.virtual).reduce((a,b)=>a+b,0);
 Object.assign(stats,{demand_points:n,baseline_covered:b,planning_covered:n,total_weight:w,baseline_weight:bw,planning_weight:w,point_coverage:n?b/n:null,planning_point_coverage:n?1:null,weight_coverage:w?bw/w:null,planning_weight_coverage:w?1:null});
 return {points:aggregate(points,view,true),visibleCount:points.reduce((s,p)=>s+p.count,0),national:true,metrics:stats};}
function detail(id){if(!dataset)throw Error('请先选择地区');const ds=dataset,r=ds.demands.get(id)||ds.nodes.get(id);if(!r)throw Error('未找到该对象');const kind=ds.demands.has(id)?'demand':'node',row={...r,...(ds.virtual.get(id)||{})},up=[],down=ds.children.get(id)||[],seen=new Set();let current=id;
 while(ds.parents.has(current)&&!seen.has(current)){seen.add(current);const edge=ds.parents.get(current);up.push(edge);current=edge.cluster_uid;}
 const geometry=e=>{const a=ds.demands.get(e.点ID)||ds.nodes.get(e.点ID),b=ds.nodes.get(e.cluster_uid);return a&&b?{child:e.点ID,parent:e.cluster_uid,level:e.层级,action:e.coverage_action,distance:e.distance_m,radius:e.radius_m,points:[[a.纬度,a.经度],[b.纬度,b.经度]]}:null};
 const radius=kind==='node'?ds.pack.summary['coverage_radius_'+r.层级+'_km']*1000:null;
 return {id,kind,row,state:ds.states.get(id),radius,up:up.map(geometry).filter(Boolean),down:down.slice(0,200).map(geometry).filter(Boolean),downTotal:down.length,facility:ds.facilities.get(r.facility_id),members:ds.members.get(r.facility_id)||[],poi:kind==='demand'?Object.fromEntries(Object.entries(r).filter(([k])=>/^(300|500)m_/.test(k))):null};}
const api={
 async init({data}){index=data;return true},
 async overview(){if(!overviewPromise)overviewPromise=readGzip('data/planning/overview.json.gz').then(v=>overview=v).catch(err=>{overviewPromise=null;throw err});await overviewPromise;return true},
 async loadCity({path,id}){const seq=++loadSequence;controller?.abort();controller=new AbortController();let d=cache.get(id);if(!d){const pack=await readGzip('data/planning/'+path,controller.signal);if(seq!==loadSequence)throw Error('AbortError');d=makeDataset(pack)}if(seq!==loadSequence)throw Error('AbortError');cache.delete(id);cache.set(id,d);while(cache.size>2)cache.delete(cache.keys().next().value);dataset=d;return {summary:d.pack.summary,types:[...new Set(d.tables.candidates.map(r=>r.物流类型).filter(Boolean))],lands:[...new Set(d.tables.centers.map(r=>r.landuse_name).filter(Boolean))],statuses:[...new Set(d.tables.centers.map(r=>r.node_status).filter(Boolean))]};},
 cancel(){loadSequence++;controller?.abort();dataset=null;return true},
 render({filters,view,city}){return city?renderCity(filters,view):renderNational(filters,view)},
 detail({id}){return detail(id)},
 search({query}){if(!dataset)return[];const q=query.toLowerCase();return [...dataset.demands.values(),...dataset.nodes.values()].filter(r=>[r.名称,r.候选点ID,r.中心ID,r.qualified_poi_name].some(s=>String(s||'').toLowerCase().includes(q))).slice(0,25).map(r=>({id:r.候选点ID||r.中心ID,name:r.名称||r.中心ID.split('|').at(-1),level:r.层级||'需求点'}))},
 export({filters,kind,id,viewport}){if(!dataset)throw Error('请选择地区后导出原始记录');let rows,columns;if(['coverage','edges','facilities','uncovered'].includes(kind)){rows=dataset.tables[kind];columns=dataset.pack.tables[kind].columns}else if(kind==='relations'){const d=dataset;rows=d.tables.coverage.filter(r=>r.点ID===id||r.cluster_uid===id);columns=d.pack.tables.coverage.columns}else{const selected=filtered(filters,viewport);rows=kind==='centers'?selected.nodes:selected.demands;columns=dataset.pack.tables[kind].columns;if(kind==='centers'){rows=rows.map(r=>({...r,...(dataset.virtual.get(r.中心ID)||{})}));columns=[...new Set([...columns,...dataset.pack.tables.virtual_nodes.columns])]}else{rows=rows.map(r=>({...r,...dataset.states.get(r.候选点ID)}));columns=[...new Set([...columns,...dataset.pack.tables.demand_coverage.columns])]}}return {csv:csvText(rows,columns),count:rows.length}},
 debug(){return {cachedCities:cache.size,activeCity:dataset?.pack.key,demands:dataset?.demands.size,nodes:dataset?.nodes.size}}
};
self.onmessage=async e=>{const {id,method,args}=e.data;try{if(!api[method])throw Error('Unsupported operation');self.postMessage({id,result:await api[method](args||{})})}catch(error){self.postMessage({id,error:error.name==='AbortError'?'AbortError':error.message})}};
